import * as React from "react";
import { cx } from "./cx";

export interface ButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {}

/** Flush joined actions. One hairline between. */
export function ButtonGroup({ className, ...props }: ButtonGroupProps) {
  return <div role="group" className={cx("rs-btn-group", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Button group: flush joined actions, one hairline between ──
   The group owns the outer stroke and the Button radius. Inner
   joins are a start-edge only, so T-junctions do not stack rgba. */
.rs-btn-group{display:inline-flex;align-items:stretch;box-sizing:border-box;height:40px;border:1px solid var(--divider);border-radius:var(--radius-sm);overflow:hidden}
.rs-btn-group:has(> .rs-btn-sm){height:36px}
.rs-btn-group > .rs-btn-primary,.rs-btn-group > .rs-btn-ghost{box-sizing:border-box;height:auto;border:0;border-radius:0;margin:0}
.rs-btn-group > * + *{border-inline-start:1px solid var(--divider)}
.rs-btn-group > .rs-btn-primary{position:relative;z-index:1}
